const departmentID=window.location.pathname.split("/").pop(),resourceList=(e,s)=>e&&0!==e.length?"<ul class='list-group'>"+$.map(e,e=>"<li class='list-group-item'>"+s(e)+"</li>").join("")+"</ul>":"<p class='text-muted'>No items.</p>",panel=(e,s)=>"<div class='panel panel-default'><div class='panel-heading'><strong>"+escapeHtml(e)+"</strong></div><div class='panel-body'>"+s+"</div></div>",renderWorkspace=e=>{const s=e.user,a=resourceList(e.campaigns,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+escapeHtml(e.status)+"</span>"),t=resourceList(e.groups,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+(e.targets||[]).length+" members</span>"),n=resourceList(e.templates,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+escapeHtml(e.subject||"")+"</span>"),p=resourceList(e.pages,e=>"<strong>"+escapeHtml(e.name)+"</strong>"),r=resourceList(e.sending_profiles,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+escapeHtml(e.host)+"</span>"),l=resourceList(e.phishing_scenarios,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+escapeHtml(e.template.name)+" / "+escapeHtml(e.page.name)+" / "+escapeHtml(e.smtp.name)+"</span>");return"<div class='panel panel-primary'><div class='panel-heading'><h3 class='panel-title'>"+escapeHtml(s.username)+" <small>"+escapeHtml(s.role.name)+"</small></h3></div><div class='panel-body'>"+panel("Campaigns",a)+panel("Groups",t)+panel("Email Templates",n)+panel("Landing Pages",p)+panel("Sending Profiles",r)+panel("Phishing Scenarios",l)+"</div></div>"};$(document).ready(()=>{api.departments.get(departmentID).success(e=>{$("#loading").hide(),$(".page-header").text("Department: "+e.manager.username),$("#departmentWorkspace").html($.map(e.workspaces,renderWorkspace).join("")),$("#departmentWorkspace").show()}).error(e=>{$("#loading").hide(),errorFlash(e.responseJSON?e.responseJSON.message:"Error loading department workspace")})});